//! SchemaLoader — reads a canonical PluginSchema from the sealed blob catalog.
//!
//! The loader accepts only a catalog directory. A plugin-owned JSON file or
//! monolithic schema document is not a valid source of authority.

use std::path::{Path, PathBuf};
use std::sync::{Arc, RwLock};
use std::time::Instant;

use tokio::sync::broadcast;
use tracing::{info, warn};

const ZEROCLOW_ROUTER_PLUGIN_ID: &str = "chat_router";

/// Event emitted to `WatchSchema` subscribers after a successful reload.
#[derive(Clone, Debug)]
pub struct SchemaReloadEvent {
    pub event_type: String,
}

/// Shared loader state for the chat_router Axum host.
#[derive(Clone)]
pub struct SchemaLoader {
    path: Arc<RwLock<PathBuf>>,
    plugin_id: Arc<RwLock<String>>,
    schema: Arc<RwLock<serde_json::Value>>,
    reload_tx: broadcast::Sender<SchemaReloadEvent>,
    health_status: Arc<RwLock<String>>,
}

impl SchemaLoader {
    /// Create a loader and perform the initial read.
    ///
    /// Panics with a descriptive message if the sealed schema catalog is absent.
    /// This is intentional: the sealed catalog must start first.
    pub fn new(path: impl Into<PathBuf>) -> anyhow::Result<Self> {
        Self::new_for_plugin(path, ZEROCLOW_ROUTER_PLUGIN_ID)
    }

    /// Create a loader for a specific plugin id and perform the initial read.
    pub fn new_for_plugin(
        path: impl Into<PathBuf>,
        plugin_id: impl Into<String>,
    ) -> anyhow::Result<Self> {
        let path = Arc::new(RwLock::new(path.into()));
        let loader = Self {
            path,
            plugin_id: Arc::new(RwLock::new(plugin_id.into())),
            schema: Arc::new(RwLock::new(serde_json::Value::Null)),
            reload_tx: broadcast::channel(16).0,
            health_status: Arc::new(RwLock::new(String::from("ok"))),
        };
        loader.load()?;
        Ok(loader)
    }

    /// Synchronous load used by `new()` for the initial read.
    ///
    /// Logs a warning if the operation exceeds the 50 ms budget.
    pub fn load(&self) -> anyhow::Result<()> {
        let start = Instant::now();
        let path = self.path.read().unwrap().clone();
        if !path.is_dir() {
            return Err(anyhow::anyhow!(
                "plugin catalog must be a directory containing sealed blobs: {}",
                path.display()
            ));
        }
        self.load_from_blob_catalog(&path, start)
    }

    /// Read the plugin's canonical schema from its sealed blob in a catalog
    /// dir. The blob in the catalog IS the plugin — no monolith, no registry.
    fn load_from_blob_catalog(&self, dir: &Path, start: Instant) -> anyhow::Result<()> {
        let plugin_id = self.plugin_id();
        let schema =
            crate::sealed_schema_reader::read_manifest_pinned_plugin_schema(dir, &plugin_id)?;
        let value = serde_json::to_value(&schema)?;
        let bytes = serde_json::to_vec(&value)?;
        Self::parse_and_store(self, &bytes, start, dir)
    }

    /// Asynchronous reload used by `SIGHUP` and the D-Bus object.
    pub async fn reload(&self) -> anyhow::Result<()> {
        let start = Instant::now();
        let path = self.path.read().unwrap().clone();
        if !path.is_dir() {
            return Err(anyhow::anyhow!(
                "plugin catalog must be a directory containing sealed blobs: {}",
                path.display()
            ));
        }
        tokio::task::spawn_blocking({
            let loader = self.clone();
            move || loader.load_from_blob_catalog(&path, start)
        })
        .await
        .map_err(|e| anyhow::anyhow!("reload task panicked: {}", e))?
    }

    fn parse_and_store(&self, bytes: &[u8], start: Instant, path: &Path) -> anyhow::Result<()> {
        let text = std::str::from_utf8(bytes).map_err(|e| {
            anyhow::anyhow!(
                "sealed plugin schema at {} is not valid UTF-8: {}",
                path.display(),
                e
            )
        })?;
        let value: serde_json::Value = serde_json::from_str(text).map_err(|e| {
            anyhow::anyhow!(
                "sealed plugin schema at {} is not valid JSON: {}",
                path.display(),
                e
            )
        })?;
        let plugin_id = self.plugin_id();
        if value.get("name").and_then(|name| name.as_str()) != Some(plugin_id.as_str()) {
            return Err(anyhow::anyhow!(
                "sealed catalog at {} does not contain '{}'",
                path.display(),
                plugin_id
            ));
        }

        {
            let mut schema = self.schema.write().unwrap();
            *schema = value;
        }

        let elapsed = start.elapsed();
        if elapsed > std::time::Duration::from_millis(50) {
            warn!(
                elapsed_ms = elapsed.as_millis(),
                plugin_id = %self.plugin_id(),
                "plugin schema reload exceeded 50 ms budget"
            );
        } else {
            info!(
                elapsed_ms = elapsed.as_millis(),
                plugin_id = %self.plugin_id(),
                "plugin schema loaded"
            );
        }

        let mut health = self.health_status.write().unwrap();
        *health = "ok".to_string();

        Ok(())
    }

    /// Clone the current schema value.
    pub async fn get(&self) -> serde_json::Value {
        self.schema.read().unwrap().clone()
    }

    /// Return the configured sealed catalog directory.
    pub fn path(&self) -> PathBuf {
        self.path.read().unwrap().clone()
    }

    /// Return the plugin id selected from the sealed catalog.
    pub fn plugin_id(&self) -> String {
        self.plugin_id.read().unwrap().clone()
    }

    /// Update the plugin id; the next `load()` reads that plugin's sealed blob.
    pub fn set_plugin_id(&self, plugin_id: impl Into<String>) {
        let mut id = self.plugin_id.write().unwrap();
        *id = plugin_id.into();
    }

    /// Update the sealed catalog directory; the next `load()` reads from it.
    pub fn set_path(&self, path: impl Into<PathBuf>) {
        let mut p = self.path.write().unwrap();
        *p = path.into();
    }

    /// Return a handle to the reload broadcast channel.
    pub fn reload_tx(&self) -> broadcast::Sender<SchemaReloadEvent> {
        self.reload_tx.clone()
    }

    /// Return the current health status string.
    pub async fn health_status(&self) -> String {
        self.health_status.read().unwrap().clone()
    }

    /// Set health status (used by the D-Bus object and server startup).
    pub async fn set_health_status(&self, status: String) {
        let mut h = self.health_status.write().unwrap();
        *h = status;
    }

    /// Spawn a task that reloads the schema on `SIGHUP` and broadcasts a
    /// plugin schema reload event.
    pub fn watch_sighup(self: Arc<Self>) -> tokio::task::JoinHandle<()> {
        tokio::spawn(async move {
            let mut sig =
                match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::hangup()) {
                    Ok(s) => s,
                    Err(e) => {
                        warn!(error = %e, "failed to install SIGHUP handler; manual reloads only");
                        return;
                    }
                };

            loop {
                sig.recv().await;
                info!(
                    subid = "evt.service.plugin-schema.reloaded@v1",
                    plugin_id = %self.plugin_id(),
                    "SIGHUP received"
                );
                match self.reload().await {
                    Ok(()) => {
                        let _ = self.reload_tx.send(SchemaReloadEvent {
                            event_type: "reload".to_string(),
                        });
                    }
                    Err(e) => {
                        warn!(error = %e, "SIGHUP reload failed");
                        let mut health = self.health_status.write().unwrap();
                        *health = e.to_string();
                    }
                }
            }
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn seal(dir: &Path, schema: op_state_store::PluginSchema) {
        let blob = op_blob::blobify_plugin_schema("chat_router", schema);
        op_blob::catalog::BlobStore::open(dir)
            .unwrap()
            .write(&blob)
            .unwrap();
    }

    #[tokio::test]
    async fn should_load_schema_from_live_catalog() {
        let dir = tempfile::tempdir().unwrap();
        let value = op_state_store::PluginSchema::builder("chat_router")
            .version("1.0.0")
            .description("test schema")
            .build();
        let path = dir.path();
        seal(path, value);
        let loader = SchemaLoader::new(path).unwrap();
        let loaded = loader.get().await;
        assert_eq!(loaded["name"], "chat_router");
        assert_eq!(loaded["version"], "1.0.0");
        assert_eq!(loader.health_status().await, "ok");
    }

    #[tokio::test]
    async fn should_reject_direct_plugin_schema_file() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("chat_router.json");
        std::fs::write(&path, "{}").unwrap();
        let error = SchemaLoader::new(&path)
            .err()
            .expect("direct schema file must be rejected");
        assert!(error.to_string().contains("catalog must be a directory"));
    }

    #[tokio::test]
    async fn should_reject_blob_without_catalog_manifest() {
        let dir = tempfile::tempdir().unwrap();
        let schema = op_state_store::PluginSchema::builder("chat_router").build();
        op_blob::blobify_plugin_schema("chat_router", schema)
            .write_to_dir(dir.path())
            .unwrap();
        assert!(SchemaLoader::new(dir.path()).is_err());
    }

    #[tokio::test]
    async fn should_reload_schema_on_sighup() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path();
        let initial = op_state_store::PluginSchema::builder("chat_router")
            .version("1.0.0")
            .description("initial")
            .build();
        seal(path, initial.clone());
        let loader = Arc::new(SchemaLoader::new(path).unwrap());
        let mut rx = loader.reload_tx().subscribe();

        // Simulate a reload by calling load directly and sending the event.
        loader.load().unwrap();
        let _ = loader.reload_tx.send(SchemaReloadEvent {
            event_type: "reload".to_string(),
        });

        // Verify the broadcast is received.
        let event = rx.recv().await.unwrap();
        assert_eq!(event.event_type, "reload");
        assert_eq!(loader.get().await["version"], "1.0.0");

        // Update the file and reload again.
        let updated = op_state_store::PluginSchema::builder("chat_router")
            .version("2.0.0")
            .description("updated")
            .build();
        seal(path, updated);
        // A stale file is not an authority: only the manifest-pinned blob is.
        op_blob::blobify_plugin_schema("chat_router", initial)
            .write_to_dir(path)
            .unwrap();
        loader.load().unwrap();
        let _ = loader.reload_tx.send(SchemaReloadEvent {
            event_type: "reload".to_string(),
        });

        let event = rx.recv().await.unwrap();
        assert_eq!(event.event_type, "reload");
        assert_eq!(loader.get().await["version"], "2.0.0");
    }
}

crates/op-grpc-bridge/src/cron_observer..content:
//! Event-driven observation of autonomous native cron executions.
//!
//! `/api/events` is a wakeup source only. The event payload is never persisted,
//! logged, or projected. Every accepted `cron_result` causes one complete,
//! bounded `/api/cron` readback, which MutationEngine commits before notifying
//! its consumers.

use crate::{
    cron_dispatch, cron_gateway::ZeroClawCronGateway, cron_methods::CronMethods,
    mutation_engine::MutationEngine, chat_router_runtime::ChatRouterRuntimeClient,
};
use anyhow::{Context, Result, bail, ensure};
use futures::StreamExt;
use std::{future::Future, sync::Arc, time::Duration};

const MAX_SSE_FRAME_BYTES: usize = 256 * 1024;
const MAX_WAKEUPS_PER_CHUNK: usize = 1024;
const MAX_RECONNECTS: usize = 8;
const RECONNECT_DELAYS: [Duration; MAX_RECONNECTS] = [
    Duration::from_millis(250),
    Duration::from_millis(500),
    Duration::from_secs(1),
    Duration::from_secs(2),
    Duration::from_secs(4),
    Duration::from_secs(5),
    Duration::from_secs(5),
    Duration::from_secs(5),
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Wakeup {
    CronResult,
    Gap,
}

#[derive(Default)]
struct SseDecoder {
    pending: Vec<u8>,
}

impl SseDecoder {
    fn push(&mut self, chunk: &[u8]) -> Result<Vec<Wakeup>> {
        let mut wakeups = Vec::new();
        for byte in chunk {
            self.pending.push(*byte);
            let delimiter_len = if self.pending.ends_with(b"\r\n\r\n") {
                Some(4)
            } else if self.pending.ends_with(b"\n\n") {
                Some(2)
            } else {
                None
            };
            ensure!(
                self.pending.len() <= MAX_SSE_FRAME_BYTES,
                "native event frame exceeds {MAX_SSE_FRAME_BYTES} bytes"
            );
            let Some(delimiter_len) = delimiter_len else {
                continue;
            };
            self.pending.truncate(self.pending.len() - delimiter_len);
            let frame = std::mem::take(&mut self.pending);
            if let Some(wakeup) = parse_frame(&frame)? {
                wakeups.push(wakeup);
                ensure!(
                    wakeups.len() <= MAX_WAKEUPS_PER_CHUNK,
                    "native event chunk contains more than {MAX_WAKEUPS_PER_CHUNK} state wakeups"
                );
            }
        }
        Ok(wakeups)
    }

    fn finish(self) -> Result<()> {
        ensure!(
            self.pending.iter().all(u8::is_ascii_whitespace),
            "native event stream ended with a truncated frame"
        );
        Ok(())
    }
}

fn parse_frame(frame: &[u8]) -> Result<Option<Wakeup>> {
    let frame = std::str::from_utf8(frame).context("native event frame is not UTF-8")?;
    let mut event_name = None;
    let mut data = String::new();
    for line in frame.lines() {
        let line = line.strip_suffix('\r').unwrap_or(line);
        if line.starts_with(':') || line.is_empty() {
            continue;
        }
        if let Some(value) = line.strip_prefix("event:") {
            event_name = Some(value.trim());
        } else if let Some(value) = line.strip_prefix("data:") {
            if !data.is_empty() {
                data.push('\n');
            }
            data.push_str(value.strip_prefix(' ').unwrap_or(value));
            ensure!(
                data.len() <= MAX_SSE_FRAME_BYTES,
                "native event data exceeds {MAX_SSE_FRAME_BYTES} bytes"
            );
        }
    }
    if event_name == Some("gap") {
        return Ok(Some(Wakeup::Gap));
    }
    if data.is_empty() {
        return Ok(None);
    }

    // Parse only long enough to identify the wakeup. In particular, never
    // retain, return, or log the native `output` field carried by cron_result.
    let value: serde_json::Value =
        serde_json::from_str(&data).context("native event data is invalid JSON")?;
    if value.get("type").and_then(serde_json::Value::as_str) != Some("cron_result") {
        return Ok(None);
    }
    let job_id = value
        .get("job_id")
        .and_then(serde_json::Value::as_str)
        .context("native cron_result has no job_id")?;
    ensure!(
        !job_id.is_empty() && job_id.len() <= 256 && !job_id.chars().any(char::is_control),
        "native cron_result has an invalid job_id"
    );
    Ok(Some(Wakeup::CronResult))
}

async fn observe_connection(
    engine: &MutationEngine,
    client: &ChatRouterRuntimeClient,
    methods: &CronMethods,
) -> Result<()> {
    // Subscribe before the first hydration. Events produced during the bounded
    // readback queue in the native response rather than falling into a gap.
    let response = client
        .open_gateway_event_stream()
        .await
        .map_err(|_| anyhow::anyhow!("native cron event subscription is unavailable"))?;
    drive_event_stream(response.bytes_stream(), || async {
        cron_dispatch::publish_observed_snapshot(engine, methods).await
    })
    .await
}

async fn drive_event_stream<S, B, E, P, F>(stream: S, mut publish: P) -> Result<()>
where
    S: futures::Stream<Item = std::result::Result<B, E>>,
    B: AsRef<[u8]>,
    E: std::fmt::Display,
    P: FnMut() -> F,
    F: Future<Output = Result<()>>,
{
    // The caller has already established the subscription. This initial
    // complete readback closes the subscribe/hydrate race.
    publish()
        .await
        .context("initial native cron snapshot publication failed")?;
    let mut decoder = SseDecoder::default();
    futures::pin_mut!(stream);
    while let Some(chunk) = stream.next().await {
        let chunk = chunk.map_err(|_| anyhow::anyhow!("native cron event stream failed"))?;
        for wakeup in decoder.push(chunk.as_ref())? {
            match wakeup {
                Wakeup::CronResult => {
                    publish()
                        .await
                        .context("cron_result snapshot publication failed")?;
                }
                Wakeup::Gap => bail!("native cron event stream reported a delivery gap"),
            }
        }
    }
    decoder.finish()?;
    bail!("native cron event stream closed")
}

/// Observe native cron wakeups with a finite reconnect budget. Reconnection is
/// attempted only after an explicit stream close/error/gap. Every newly opened
/// stream is established before its rehydration read; there is no polling or
/// heartbeat-triggered state read.
pub(crate) async fn observe(engine: Arc<MutationEngine>) -> Result<()> {
    let client = ChatRouterRuntimeClient::from_env();
    let gateway = Arc::new(ZeroClawCronGateway::from_client(client.clone()));
    let methods = CronMethods::new(gateway);

    let mut last_error = None;
    for attempt in 0..=MAX_RECONNECTS {
        if attempt > 0 {
            tokio::time::sleep(RECONNECT_DELAYS[attempt - 1]).await;
        }
        match observe_connection(&engine, &client, &methods).await {
            Ok(()) => return Ok(()),
            Err(error) => last_error = Some(error),
        }
    }
    Err(last_error.unwrap_or_else(|| anyhow::anyhow!("native cron observer ended")))
        .context("native cron observer exhausted its bounded reconnect budget")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fragmented_cron_result_is_one_wakeup_and_output_is_not_returned() {
        let mut decoder = SseDecoder::default();
        assert!(
            decoder
                .push(b"data: {\"type\":\"cron_result\",\"job_id\":\"job-1\",\"out")
                .unwrap()
                .is_empty()
        );
        assert_eq!(
            decoder.push(b"put\":\"private result\"}\n\n").unwrap(),
            vec![Wakeup::CronResult]
        );
        decoder.finish().unwrap();
    }

    #[test]
    fn explicit_gap_is_not_treated_as_a_state_event() {
        let mut decoder = SseDecoder::default();
        assert_eq!(
            decoder.push(b"event: gap\ndata: 7\n\n").unwrap(),
            vec![Wakeup::Gap]
        );
    }

    #[test]
    fn unrelated_events_and_keepalives_do_not_wake_state_reads() {
        let mut decoder = SseDecoder::default();
        assert!(decoder.push(b": keepalive\n\n").unwrap().is_empty());
        assert!(
            decoder
                .push(b"data: {\"type\":\"tool_call\",\"output\":\"private\"}\n\n")
                .unwrap()
                .is_empty()
        );
    }

    #[test]
    fn malformed_oversized_and_truncated_frames_fail_closed() {
        let mut malformed = SseDecoder::default();
        assert!(malformed.push(b"data: not-json\n\n").is_err());

        let mut oversized = SseDecoder::default();
        assert!(
            oversized
                .push(&vec![b'x'; MAX_SSE_FRAME_BYTES + 1])
                .is_err()
        );

        let mut truncated = SseDecoder::default();
        truncated.push(b"data: {\"type\":").unwrap();
        assert!(truncated.finish().is_err());
    }

    #[test]
    fn multiple_cron_results_preserve_one_wakeup_per_real_frame() {
        let mut decoder = SseDecoder::default();
        let frames = b"data: {\"type\":\"cron_result\",\"job_id\":\"a\"}\n\ndata: {\"type\":\"cron_result\",\"job_id\":\"b\"}\n\n";
        assert_eq!(
            decoder.push(frames).unwrap(),
            vec![Wakeup::CronResult, Wakeup::CronResult]
        );
    }

    #[tokio::test]
    async fn driver_hydrates_once_then_reads_once_per_cron_result() {
        let stream = futures::stream::iter(vec![Ok::<_, &'static str>(
            b"data: {\"type\":\"tool_call\"}\n\ndata: {\"type\":\"cron_result\",\"job_id\":\"a\",\"output\":\"secret\"}\n\ndata: {\"type\":\"cron_result\",\"job_id\":\"b\"}\n\n"
                .as_slice(),
        )]);
        let publications = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let publish = publications.clone();
        let result = drive_event_stream(stream, move || {
            let publish = publish.clone();
            async move {
                publish.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                Ok(())
            }
        })
        .await;
        assert!(
            result.is_err(),
            "finite stream closure requires rehydration"
        );
        assert_eq!(
            publications.load(std::sync::atomic::Ordering::SeqCst),
            3,
            "one initial hydration plus one full read per cron_result"
        );
    }

    #[tokio::test]
    async fn explicit_gap_stops_before_following_frame() {
        let stream = futures::stream::iter(vec![Ok::<_, &'static str>(
            b"event: gap\ndata: 1\n\ndata: {\"type\":\"cron_result\",\"job_id\":\"late\"}\n\n"
                .as_slice(),
        )]);
        let publications = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let publish = publications.clone();
        assert!(
            drive_event_stream(stream, move || {
                let publish = publish.clone();
                async move {
                    publish.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    Ok(())
                }
            })
            .await
            .is_err()
        );
        assert_eq!(
            publications.load(std::sync::atomic::Ordering::SeqCst),
            1,
            "gap forces reconnect/rehydration without consuming later frames"
        );
    }
}

crates/op-grpc-bridge/src/cron_gateway.r.content:
//! Exact v0.8.4 cron route mapping over the existing hardened tched-router
//! runtime client. No second reqwest client or bearer authority is introduced.

use anyhow::{Result, anyhow};
use async_trait::async_trait;
use op_plugins::state_plugins::cron::*;
use serde::Deserialize;

use crate::cron_methods::{CronGateway, ProviderMutation};
use crate::chat_router_runtime::{
    GatewayJsonRequest, GatewayMethod, GatewayProfile, GatewayRequestError,
    ChatRouterRuntimeClient,
};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct JobsResponse {
    jobs: Vec<CronJobRecord>,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RunsResponse {
    runs: Vec<CronRunRecord>,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct JobResponse {
    status: String,
    job: CronJobRecord,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct StatusResponse {
    status: String,
}

pub(crate) struct ZeroClawCronGateway {
    client: ChatRouterRuntimeClient,
}
impl ZeroClawCronGateway {
    pub(crate) fn production() -> Self {
        Self {
            client: ChatRouterRuntimeClient::from_env(),
        }
    }

    pub(crate) fn from_client(client: ChatRouterRuntimeClient) -> Self {
        Self { client }
    }
}

fn encoded_segment(raw: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(raw.len());
    for byte in raw.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'.' | b'_' | b'~') {
            out.push(char::from(byte));
        } else {
            out.push('%');
            out.push(char::from(HEX[(byte >> 4) as usize]));
            out.push(char::from(HEX[(byte & 0x0f) as usize]));
        }
    }
    out
}

fn read_error(error: GatewayRequestError) -> anyhow::Error {
    match error {
        GatewayRequestError::BeforeEffect(_) => {
            anyhow!("chat_router cron request failed before a provider result")
        }
        GatewayRequestError::InvalidResponse(_) => {
            anyhow!("chat_router cron response was unavailable or invalid")
        }
        GatewayRequestError::IndeterminateMutation(_) => {
            anyhow!("unexpected indeterminate classification for cron read")
        }
        GatewayRequestError::ProviderRejected { status, .. } => {
            anyhow!("chat_router rejected cron request with HTTP {status}")
        }
    }
}

fn mutation<T>(result: std::result::Result<T, GatewayRequestError>) -> Result<ProviderMutation<T>> {
    match result {
        Ok(value) => Ok(ProviderMutation::Completed(value)),
        Err(GatewayRequestError::IndeterminateMutation(_)) => Ok(ProviderMutation::Indeterminate(
            "native cron request may have taken effect; observe current state before retrying".into(),
        )),
        Err(GatewayRequestError::BeforeEffect(_)) => {
            Err(anyhow!("chat_router cron mutation failed before submission"))
        }
        Err(GatewayRequestError::ProviderRejected { status, .. }) => {
            Err(anyhow!("chat_router rejected cron mutation with HTTP {status}"))
        }
        // The shared transport promises this only for reads. Fail closed if a
        // future implementation violates that classification.
        Err(GatewayRequestError::InvalidResponse(_)) => Ok(ProviderMutation::Indeterminate(
            "native cron response was invalid after mutation submission; observe current state before retrying".into(),
        )),
    }
}

fn completed_job(
    result: std::result::Result<JobResponse, GatewayRequestError>,
) -> Result<ProviderMutation<CronJobRecord>> {
    match mutation(result)? {
        ProviderMutation::Completed(response) => {
            if response.status == "ok" {
                Ok(ProviderMutation::Completed(response.job))
            } else {
                Ok(ProviderMutation::Indeterminate(
                    "native cron response did not establish mutation completion; observe current state before retrying".into(),
                ))
            }
        }
        ProviderMutation::Indeterminate(detail) => Ok(ProviderMutation::Indeterminate(detail)),
    }
}

#[async_trait]
impl CronGateway for ZeroClawCronGateway {
    async fn list_jobs(&self) -> Result<Vec<CronJobRecord>> {
        let response: JobsResponse = self
            .client
            .send_gateway_json(GatewayJsonRequest {
                method: GatewayMethod::Get,
                relative_path: "/api/cron",
                query: &[],
                body: None,
                operation: "list cron jobs",
                profile: GatewayProfile::Config,
                mutation: false,
            })
            .await
            .map_err(read_error)?;
        Ok(response.jobs)
    }

    async fn list_runs(&self, job_id: &str, limit: u32) -> Result<Vec<CronRunRecord>> {
        let path = format!("/api/cron/{}/runs", encoded_segment(job_id));
        let limit = limit.to_string();
        let response: RunsResponse = self
            .client
            .send_gateway_json(GatewayJsonRequest {
                method: GatewayMethod::Get,
                relative_path: &path,
                query: &[("limit", limit.as_str())],
                body: None,
                operation: "list cron history",
                profile: GatewayProfile::Config,
                mutation: false,
            })
            .await
            .map_err(read_error)?;
        Ok(response.runs)
    }

    async fn create_job(&self, input: CreateJobInput) -> Result<ProviderMutation<CronJobRecord>> {
        let body = serde_json::to_value(input)?;
        completed_job(
            self.client
                .send_gateway_json(GatewayJsonRequest {
                    method: GatewayMethod::Post,
                    relative_path: "/api/cron",
                    query: &[],
                    body: Some(&body),
                    operation: "create cron job",
                    profile: GatewayProfile::Config,
                    mutation: true,
                })
                .await,
        )
    }

    async fn update_job(&self, input: UpdateJobInput) -> Result<ProviderMutation<CronJobRecord>> {
        let path = format!("/api/cron/{}", encoded_segment(&input.job_id));
        let mut body = serde_json::to_value(&input)?;
        let object = body
            .as_object_mut()
            .expect("typed update serializes as object");
        object.remove("job_id");
        object.retain(|_, value| !value.is_null());
        completed_job(
            self.client
                .send_gateway_json(GatewayJsonRequest {
                    method: GatewayMethod::Patch,
                    relative_path: &path,
                    query: &[],
                    body: Some(&body),
                    operation: "update cron job",
                    profile: GatewayProfile::Config,
                    mutation: true,
                })
                .await,
        )
    }

    async fn delete_job(&self, job_id: &str) -> Result<ProviderMutation<()>> {
        let path = format!("/api/cron/{}", encoded_segment(job_id));
        match mutation::<StatusResponse>(
            self.client
                .send_gateway_json(GatewayJsonRequest {
                    method: GatewayMethod::Delete,
                    relative_path: &path,
                    query: &[],
                    body: None,
                    operation: "delete cron job",
                    profile: GatewayProfile::Config,
                    mutation: true,
                })
                .await,
        )? {
            ProviderMutation::Completed(response) => {
                if response.status == "ok" {
                    Ok(ProviderMutation::Completed(()))
                } else {
                    Ok(ProviderMutation::Indeterminate(
                        "native cron response did not establish delete completion; observe current state before retrying".into(),
                    ))
                }
            }
            ProviderMutation::Indeterminate(detail) => Ok(ProviderMutation::Indeterminate(detail)),
        }
    }

    async fn run_job(&self, job_id: &str) -> Result<ProviderMutation<ManualRunResult>> {
        let path = format!("/api/cron/{}/run", encoded_segment(job_id));
        mutation(
            self.client
                .send_gateway_json(GatewayJsonRequest {
                    method: GatewayMethod::Post,
                    relative_path: &path,
                    query: &[],
                    body: None,
                    operation: "run cron job",
                    profile: GatewayProfile::LongRunning,
                    mutation: true,
                })
                .await,
        )
    }
}

