// Prior names: zeroclow_router, tched_router, ZeroClawRouterService.
// chat_router gRPC schema host contract.
// This proto only defines the service envelope. The actual PluginSchema payload
// is serialized JSON from `chat_router_schema()` in `op-plugins` — never hand-edited
// structs here.
syntax = "proto3";
package chat_router;

service ChatRouterService {
  // Return the current plugin-owned PluginSchema JSON plus trace headers.
  rpc GetSchema(GetSchemaRequest) returns (SchemaResponse);

  // Stream the initial schema, then emit a new event on every reload.
  rpc WatchSchema(WatchSchemaRequest) returns (stream SchemaEvent);
}

message GetSchemaRequest {}
message WatchSchemaRequest {}

message SchemaResponse {
  // Canonical PluginSchema JSON serialized by `chat_router_schema()`.
  string schema_json = 1;

  // Accountability trace identifier.
  string trace_id = 2;

  // Anchored Ghostbridge session genesis from the incoming request.
  string session_genesis = 3;
}

message SchemaEvent {
  // Canonical PluginSchema JSON.
  string schema_json = 1;

  // "initial" on stream start, "reload" after a successful SIGHUP/D-Bus reload.
  string event_type = 2;
}

crates/op-grpc-bridge/build.rs.content:
use std::env;
use std::fmt::Write as _;
use std::path::PathBuf;
use std::sync::Arc;
#[path = "src/json_schema_proto.rs"]
mod json_schema_proto;
use json_schema_proto::json_schema_type_to_proto;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Prior names: ZEROCLOW_CAPTURE_BIN, ZEROCLOW_BIN, ZEROCLOW_ROUTER_CONFIG_DIR,
    // src/grpc/zeroclow_router.proto, src/grpc/tched_router.proto.
    // These selectors match chat_router_paths.
    for name in [
        "THREETCHED_CAPTURE_BIN",
        "THREETCHED_CAPTURE_MANIFEST",
        "THREETCHED_BIN",
        "THREETCHED_MANIFEST",
        "TCHED_ROUTER_CONFIG_DIR",
    ] {
        println!("cargo:rerun-if-env-changed={name}");
    }
    for (capture, runtime, default) in [
        (
            "THREETCHED_CAPTURE_BIN",
            "THREETCHED_BIN",
            "/usr/local/libexec/op-dbus/threetched/threetched",
        ),
        (
            "THREETCHED_CAPTURE_MANIFEST",
            "THREETCHED_MANIFEST",
            "/usr/share/op-dbus/threetched-manifests/tched-router.json",
        ),
    ] {
        let selected = PathBuf::from(
            env::var_os(capture)
                .or_else(|| env::var_os(runtime))
                .unwrap_or_else(|| default.into()),
        );
        // Watch both the selected link and its resolved release artifact.
        println!("cargo:rerun-if-changed={}", selected.display());
        if let Ok(resolved) = std::fs::canonicalize(&selected)
            && resolved != selected
        {
            println!("cargo:rerun-if-changed={}", resolved.display());
        }
    }
    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());
    let generated_proto = out_dir.join("plugin_methods.proto");
    let generated_routes = out_dir.join("plugin_method_routes.rs");
    let generated_contracts = out_dir.join("compiled_method_contracts.json");
    op_plugins::state_plugins::threetched::prepare_schema_capture()?;
    let plugin_methods = collect_plugin_methods();

    std::fs::write(
        &generated_proto,
        generate_plugin_methods_proto(&plugin_methods),
    )?;
    std::fs::write(
        &generated_routes,
        generate_plugin_method_routes(&plugin_methods),
    )?;
    // Compatibility evidence for this binary, never a runtime plugin catalog.
    // Preserve full method/state declarations from the collection producing routes.
    std::fs::write(
        &generated_contracts,
        generate_compiled_method_contracts(&plugin_methods)?,
    )?;

    // Compile all domain protos into a single combined FileDescriptorSet so
    // that tonic-reflection exposes every service in one query.
    //
    // Adding a new domain proto:
    //   1. Add the .proto file under proto/
    //   2. Add it to the compile_protos list below
    //   3. Add rerun-if-changed below
    //   4. Add the generated server/client to grpc_server.rs
    tonic_build::configure()
        // Generated inputs live in OUT_DIR; watching them would make this
        // script invalidate itself on the next Cargo invocation. The authored
        // proto roots and plugin inputs are explicitly watched below.
        .emit_rerun_if_changed(false)
        .build_server(true)
        .build_client(true)
        .file_descriptor_set_path(out_dir.join("operation_descriptor.bin"))
        .compile_protos(
            &[
                "proto/operation.proto",
                "proto/mail.proto",
                "proto/privacy_network.proto",
                "proto/registration.proto",
                "proto/registry.proto",
                "proto/emqx_exhook_v3.proto",
                "../op-chat/proto/chat.proto",
                "src/grpc/chat_router.proto",
                generated_proto
                    .to_str()
                    .ok_or("generated plugin proto path is not valid UTF-8")?,
            ],
            &[
                "proto",
                "../op-chat/proto",
                "src/grpc",
                out_dir
                    .to_str()
                    .ok_or("generated proto include path is not valid UTF-8")?,
            ],
        )?;

    // Watch imported authored protos as well as the entry points.
    println!("cargo:rerun-if-changed=proto");
    println!("cargo:rerun-if-changed=../op-chat/proto");
    println!("cargo:rerun-if-changed=src/grpc");
    println!("cargo:rerun-if-changed=proto/operation.proto");
    println!("cargo:rerun-if-changed=proto/mail.proto");
    println!("cargo:rerun-if-changed=proto/privacy_network.proto");
    println!("cargo:rerun-if-changed=proto/registration.proto");
    println!("cargo:rerun-if-changed=proto/registry.proto");
    println!("cargo:rerun-if-changed=proto/emqx_exhook_v3.proto");
    println!("cargo:rerun-if-changed=../op-chat/proto/chat.proto");
    println!("cargo:rerun-if-changed=src/grpc/chat_router.proto");
    println!("cargo:rerun-if-changed=../op-plugins/src/state_plugins");
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=src/json_schema_proto.rs");

    Ok(())
}

#[derive(Debug, Clone)]
struct PluginMethodSet {
    plugin_id: String,
    plugin_version: String,
    state_fields: std::collections::HashMap<String, op_state_store::FieldSchema>,
    service_name: String,
    server_module: String,
    server_type: String,
    trait_name: String,
    methods: Vec<PluginMethod>,
}

#[derive(Debug, Clone)]
struct PluginMethod {
    rpc_name: String,
    rust_name: String,
    schema_name: String,
    input_name: String,
    output_name: String,
    args: simd_json::OwnedValue,
    returns: simd_json::OwnedValue,
    declaration: op_state_store::MethodDecl,
}

fn collect_plugin_methods() -> Vec<PluginMethodSet> {
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("build plugin schema collection runtime");
    rt.block_on(async {
        let store = Arc::new(op_state_store::MemoryStore::new());
        let registry = op_plugins::DefaultPluginRegistry::new(store);
        let mut sets = Vec::new();

        for plugin_id in op_plugins::DefaultPluginRegistry::available_plugins() {
            let Ok(plugin) = registry.load_plugin(&plugin_id).await else {
                continue;
            };
            let Some(schema) = plugin.schema() else {
                continue;
            };
            if schema.methods.is_empty() {
                continue;
            }

            let mut method_names = schema.methods.keys().cloned().collect::<Vec<_>>();
            method_names.sort();
            let methods = method_names
                .into_iter()
                .map(|schema_name| {
                    let method_decl = schema
                        .methods
                        .get(&schema_name)
                        .expect("method declaration must exist");
                    let rpc_name = to_pascal_ident(&schema_name);
                    let message_prefix = to_pascal_ident(&plugin_id);
                    PluginMethod {
                        rust_name: to_snake_ident(&rpc_name),
                        rpc_name: rpc_name.clone(),
                        schema_name,
                        input_name: format!("{message_prefix}{rpc_name}Request"),
                        output_name: format!("{message_prefix}{rpc_name}Response"),
                        args: method_decl.args.clone(),
                        returns: method_decl
                            .returns
                            .clone()
                            .unwrap_or_else(|| simd_json::json!({})),
                        declaration: method_decl.clone(),
                    }
                })
                .collect::<Vec<_>>();

            let trait_name = format!("{}PluginMethods", to_pascal_ident(&plugin_id));
            sets.push(PluginMethodSet {
                plugin_id: plugin_id.clone(),
                plugin_version: schema.version.clone(),
                state_fields: schema.fields.clone(),
                service_name: trait_name.clone(),
                server_module: format!("{}_server", to_snake_ident(&trait_name)),
                server_type: format!("{}Server", trait_name),
                trait_name,
                methods,
            });
        }

        sets.sort_by(|left, right| left.plugin_id.cmp(&right.plugin_id));
        sets
    })
}

fn generate_compiled_method_contracts(
    sets: &[PluginMethodSet],
) -> Result<Vec<u8>, serde_json::Error> {
    let contracts = sets
        .iter()
        .map(|set| {
            let methods = set
                .methods
                .iter()
                .map(|method| (&method.schema_name, &method.declaration))
                .collect::<std::collections::BTreeMap<_, _>>();
            (
                &set.plugin_id,
                serde_json::json!({
                    "version": set.plugin_version,
                    "fields": set.state_fields,
                    "methods": methods
                }),
            )
        })
        .collect::<std::collections::BTreeMap<_, _>>();
    serde_json::to_vec(&contracts)
}

fn generate_plugin_methods_proto(sets: &[PluginMethodSet]) -> String {
    let mut proto = String::new();
    writeln!(proto, "syntax = \"proto3\";").unwrap();
    writeln!(proto).unwrap();
    writeln!(proto, "package operation.plugin.v1;").unwrap();
    writeln!(proto).unwrap();
    writeln!(proto, "import \"google/protobuf/struct.proto\";").unwrap();
    writeln!(proto).unwrap();

    for set in sets {
        writeln!(proto, "// PluginSchema source: {}", set.plugin_id).unwrap();
        for method in &set.methods {
            writeln!(
                proto,
                "{}",
                schema_message_proto(&method.input_name, &method.args)
            )
            .unwrap();
            writeln!(
                proto,
                "{}",
                schema_message_proto(&method.output_name, &method.returns)
            )
            .unwrap();
        }
        writeln!(proto, "service {} {{", set.service_name).unwrap();
        for method in &set.methods {
            writeln!(
                proto,
                "  rpc {}({}) returns ({});",
                method.rpc_name, method.input_name, method.output_name
            )
            .unwrap();
        }
        writeln!(proto, "}}").unwrap();
        writeln!(proto).unwrap();
    }

    proto
}

fn generate_plugin_method_routes(sets: &[PluginMethodSet]) -> String {
    let mut rust = String::new();
    writeln!(rust, "#[allow(clippy::all)]").unwrap();
    writeln!(rust, "#[allow(unused_qualifications)]").unwrap();
    writeln!(rust, "mod generated_plugin_method_routes {{").unwrap();
    writeln!(rust, "    use crate::grpc_server::OperationGrpcServer;").unwrap();
    writeln!(rust, "    use tonic::{{Request, Response, Status}};").unwrap();
    writeln!(rust).unwrap();

    for set in sets {
        writeln!(
            rust,
            "    #[tonic::async_trait]\n    impl crate::proto::plugin_methods::{}::{} for OperationGrpcServer {{",
            set.server_module, set.trait_name
        )
        .unwrap();
        for method in &set.methods {
            writeln!(
                rust,
                "        async fn {}(&self, request: Request<crate::proto::plugin_methods::{}>) -> Result<Response<crate::proto::plugin_methods::{}>, Status> {{",
                method.rust_name, method.input_name, method.output_name
            )
            .unwrap();
            writeln!(
                rust,
                "            self.call_generated_plugin_method_typed({:?}, {:?}, {:?}, {:?}, request).await",
                set.plugin_id,
                method.schema_name,
                format!("operation.plugin.v1.{}", method.input_name),
                format!("operation.plugin.v1.{}", method.output_name)
            )
            .unwrap();
            writeln!(rust, "        }}").unwrap();
        }
        writeln!(rust, "    }}").unwrap();
        writeln!(rust).unwrap();
    }

    writeln!(
        rust,
        "    pub(crate) fn add_routes(mut routes: tonic::service::Routes, server: OperationGrpcServer, validator: std::sync::Arc<crate::oracle_assertion::AssertionValidator>) -> tonic::service::Routes {{"
    )
    .unwrap();
    for set in sets {
        writeln!(
            rust,
            "        routes = routes.add_service(tonic_web::enable(crate::proto::plugin_methods::{}::{}::with_interceptor(server.clone(), crate::interceptor::make_ghostbridge_interceptor(validator.clone()))));",
            set.server_module, set.server_type
        )
        .unwrap();
    }
    writeln!(rust, "        routes").unwrap();
    writeln!(rust, "    }}").unwrap();
    writeln!(rust).unwrap();

    // Emitted from the same `sets` that produced `add_routes`, so the names
    // reflection advertises can never drift from the ones actually mounted.
    writeln!(
        rust,
        "    pub(crate) const LEGACY_PLUGIN_METHOD_SERVICES: &[(&str, &str)] = &["
    )
    .unwrap();
    for set in sets {
        writeln!(
            rust,
            "        ({:?}, {:?}),",
            set.plugin_id,
            format!("operation.plugin.v1.{}", set.service_name)
        )
        .unwrap();
    }
    writeln!(rust, "    ];").unwrap();
    writeln!(rust, "}}").unwrap();
    writeln!(
        rust,
        "pub(crate) use generated_plugin_method_routes::{{add_routes, LEGACY_PLUGIN_METHOD_SERVICES}};"
    )
    .unwrap();
    rust
}

fn schema_message_proto(message_name: &str, schema: &simd_json::OwnedValue) -> String {
    let fields = schema_fields(schema);
    let mut proto = format!("message {} {{\n", message_name);

    if fields.is_empty() {
        proto.push_str("  // Empty schema object.\n");
    }

    for field in fields {
        let repeated = if field.repeated {
            "repeated "
        } else if json_schema_proto::needs_scalar_presence(&field.proto_type, field.repeated) {
            "optional "
        } else {
            ""
        };
        proto.push_str(&format!(
            "  {}{} {} = {}{};\n",
            repeated,
            field.proto_type,
            field.name,
            field.number,
            field.json_name.as_ref().map_or_else(String::new, |name| {
                format!(" [json_name = {}]", proto_string_literal(name))
            })
        ));
    }

    proto.push_str("}\n");
    proto
}

#[derive(Debug, Clone)]
struct ProtoField {
    name: String,
    json_name: Option<String>,
    proto_type: String,
    repeated: bool,
    number: i32,
}

fn schema_fields(schema: &simd_json::OwnedValue) -> Vec<ProtoField> {
    let Ok(json_schema) = serde_json::to_value(schema) else {
        return vec![fallback_field("payload", "google.protobuf.Value", false)];
    };

    let Some(properties) = json_schema
        .get("properties")
        .and_then(|value| value.as_object())
    else {
        return Vec::new();
    };

    let mut fields = properties.iter().collect::<Vec<_>>();
    fields.sort_by_key(|(name, _)| *name);
    op_blob::descriptor::validate_proto_field_aliases(properties.keys().map(String::as_str))
        .expect("JSON Schema properties have ambiguous protobuf field aliases");

    fields
        .into_iter()
        .map(|(name, property)| {
            let (proto_type, repeated) = json_schema_type_to_proto(property);
            let proto_name = op_blob::descriptor::proto_field_name(name);
            ProtoField {
                json_name: (proto_name != *name).then(|| name.clone()),
                name: proto_name,
                proto_type,
                repeated,
                number: stable_field_number(name),
            }
        })
        .collect()
}

fn fallback_field(name: &str, proto_type: &str, repeated: bool) -> ProtoField {
    ProtoField {
        name: name.to_string(),
        json_name: None,
        proto_type: proto_type.to_string(),
        repeated,
        number: stable_field_number(name),
    }
}

fn stable_field_number(name: &str) -> i32 {
    const FNV_OFFSET: u32 = 0x811c9dc5;
    const FNV_PRIME: u32 = 0x01000193;
    const MAX_FIELD: u32 = 536_870_911;
    const RESERVED_START: u32 = 19_000;
    const RESERVED_END: u32 = 19_999;

    let mut hash = FNV_OFFSET;
    for byte in name.as_bytes() {
        hash ^= u32::from(*byte);
        hash = hash.wrapping_mul(FNV_PRIME);
    }

    let mut number = (hash % MAX_FIELD).max(1);
    if (RESERVED_START..=RESERVED_END).contains(&number) {
        number += RESERVED_END - RESERVED_START + 1;
    }
    number as i32
}

fn proto_string_literal(value: &str) -> String {
    let mut literal = String::from("\"");
    for byte in value.bytes() {
        match byte {
            b'"' => literal.push_str("\\\""),
            b'\\' => literal.push_str("\\\\"),
            0x20..=0x7e => literal.push(char::from(byte)),
            _ => write!(literal, "\\{byte:03o}").unwrap(),
        }
    }
    literal.push('"');
    literal
}

fn to_pascal_ident(value: &str) -> String {
    let mut ident = String::new();
    let mut uppercase_next = true;
    for ch in value.chars() {
        if ch.is_ascii_alphanumeric() {
            if uppercase_next {
                ident.push(ch.to_ascii_uppercase());
                uppercase_next = false;
            } else {
                ident.push(ch);
            }
        } else {
            uppercase_next = true;
        }
    }
    if ident.is_empty() {
        "Generated".to_string()
    } else if ident.chars().next().is_some_and(|ch| ch.is_ascii_digit()) {
        format!("P{}", ident)
    } else {
        ident
    }
}

fn to_snake_ident(value: &str) -> String {
    let mut ident = String::new();
    let mut previous_was_underscore = false;
    for (idx, ch) in value.chars().enumerate() {
        if ch.is_ascii_alphanumeric() {
            if ch.is_ascii_uppercase() {
                if idx > 0 && !previous_was_underscore {
                    ident.push('_');
                }
                ident.push(ch.to_ascii_lowercase());
                previous_was_underscore = false;
            } else {
                ident.push(ch);
                previous_was_underscore = false;
            }
        } else if !previous_was_underscore && !ident.is_empty() {
            ident.push('_');
            previous_was_underscore = true;
        }
    }
    while ident.ends_with('_') {
        ident.pop();
    }
    if ident.is_empty() {
        "generated".to_string()
    } else if ident.chars().next().is_some_and(|ch| ch.is_ascii_digit()) {
        format!("p_{}", ident)
    } else {
        ident
    }
}

crates/op-plugins/src/state_plugins/thre.content:
//! Binary-discovered threetched methods owned by one sealed plugin contract.
//!
//! The binary supplies command words, flags and token schemas. This plugin owns
//! admission policy; help text cannot establish that a command is read-only.
//! opblob is the sole sealer. Filesystem and transport consumers project its
//! sealed declarations and dispatch through the existing MutationEngine gate.

use std::fs::File;
use std::io::Read;
use std::path::Path;
use std::process::Command;
use std::sync::{Arc, OnceLock, atomic::{AtomicBool, Ordering}};

use anyhow::{Context, Result, bail, ensure};
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::method_receipt::UnsupportedBeforeEffect;
use op_state_store::{CapabilityDecl, MethodDecl, PluginSchema, SideEffect};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::{Digest, Sha256};
use simd_json::OwnedValue;
use tched_fs::threetched_surface::{SurfaceSnapshot, ThreetchedSurface};

pub const PLUGIN_NAME: &str = "threetched";
const VERSION: &str = "1.0.0";
const MANIFEST_FORMAT: &str = "opdbus.threetched.v1";

/// Immutable discovery evidence, never a copy of the running configuration.
/// Capture selectors are build/seal inputs; these paths select the installed
/// runtime and stay identical when the candidate is staged into a release.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ThreetchedState {
    pub binary: String,
    pub manifest: String,
    pub config_dir: String,
    pub binary_sha256: String,
    pub manifest_sha256: String,
    pub surface: Value,
}

struct Captured {
    state: ThreetchedState,
    surface: ThreetchedSurface,
    version: String,
}

static CAPTURED: OnceLock<std::result::Result<Captured, String>> = OnceLock::new();

/// Explicit authoring entry point for opblob and generated bridge contracts.
/// Each opblob command is a new process: every seal captures fresh bytes, shared
/// by all consumers in that invocation. Runtime never initializes this cache.
pub fn prepare_schema_capture() -> Result<()> {
    CAPTURED.get_or_init(|| capture().map_err(|error| format!("{error:#}")))
        .as_ref().map(|_| ()).map_err(|error| anyhow::anyhow!("{error}"))
}

pub(crate) fn is_schema_capture() -> bool {
    CAPTURED.get().is_some()
}

fn captured() -> Result<&'static Captured> {
    CAPTURED
        .get().context("threetched capture requires explicit schema preparation; runtime uses sealed blobs")?
        .as_ref()
        .map_err(|error| anyhow::anyhow!("{error}"))
}

pub(crate) fn sealed_schema(plugin_id: &str) -> Result<PluginSchema> {
    let directory = std::env::var_os("OP_BLOB_CATALOG_DIR")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| op_blob::catalog::DEFAULT_SHM_DIR.into());
    op_blob::catalog::read_plugin_state_store_schema(&directory, plugin_id)
        .with_context(|| format!("missing or invalid sealed {plugin_id} schema in {}", directory.display()))
}

pub(crate) fn sealed_state(plugin_id: &str) -> Result<OwnedValue> {
    sealed_schema(plugin_id)?.example
        .with_context(|| format!("sealed {plugin_id} schema has no discovery descriptor"))
}

pub(crate) fn capture_state() -> Result<&'static ThreetchedState> {
    Ok(&captured()?.state)
}

fn path_text(path: &Path) -> Result<String> {
    Ok(path.to_str().context("threetched path is not UTF-8")?.to_owned())
}

fn sha256_file(path: &Path) -> Result<String> {
    let mut file = File::open(path).with_context(|| format!("open {}", path.display()))?;
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024];
    loop {
        let count = file.read(&mut buffer)?;
        if count == 0 {
            break;
        }
        hasher.update(&buffer[..count]);
    }
    Ok(format!("{:x}", hasher.finalize()))
}

fn manifest_version(manifest: &Value, binary_hash: &str) -> Result<String> {
    ensure!(manifest["format"] == MANIFEST_FORMAT, "unsupported threetched manifest format");
    ensure!(manifest.pointer("/artifact/name").and_then(Value::as_str) == Some("threetched"), "manifest is not for the threetched executable");
    ensure!(manifest.pointer("/artifact/sha256").and_then(Value::as_str) == Some(binary_hash), "threetched executable differs from its manifest");
    let tag = manifest.pointer("/upstream/tag").and_then(Value::as_str)
        .context("threetched manifest has no upstream version")?;
    let version = tag.strip_prefix('v').filter(|value| !value.is_empty())
        .context("threetched manifest version must start with v")?;
    Ok(format!("threetched {version}"))
}

fn capture() -> Result<Captured> {
    let binary = super::chat_router_paths::binary()?;
    let manifest = super::chat_router_paths::manifest()?;
    let config_dir = super::chat_router_paths::config_dir()?;
    let (capture_binary, capture_manifest) = super::chat_router_paths::capture_paths()?;
    let manifest_sha256 = sha256_file(&capture_manifest)?;
    let descriptor: Value = serde_json::from_reader(File::open(&capture_manifest)?)?;
    let binary_sha256 = sha256_file(&capture_binary)?;
    let version = manifest_version(&descriptor, &binary_sha256)?;
    let bare_version = version.strip_prefix("threetched ")
        .expect("manifest_version prefixes the bare version").to_owned();
    let surface = ThreetchedSurface::capture_with_config(&capture_binary, &config_dir)?;
    ensure!(surface.binary_sha256() == binary_sha256, "threetched executable changed during capture");
    ensure!(surface.version() == Some(version.as_str()), "threetched version differs from its manifest");
    ensure!(sha256_file(&capture_manifest)? == manifest_sha256, "threetched manifest changed during capture");
    let state = ThreetchedState {
        binary: path_text(&binary)?,
        manifest: path_text(&manifest)?,
        config_dir: path_text(&config_dir)?,
        binary_sha256: surface.binary_sha256().to_owned(),
        manifest_sha256,
        surface: serde_json::to_value(surface.snapshot())?,
    };
    Ok(Captured { state, surface, version: bare_version })
}

/// The pinned binary surface captured once at seal.
pub(crate) fn surface() -> Result<&'static ThreetchedSurface> {
    Ok(&captured()?.surface)
}

/// The threetched `config schema` document from the same pinned capture.
pub(crate) fn config_schema() -> Result<&'static Value> {
    Ok(captured()?.surface.schema_json())
}

/// The bare upstream version (e.g. "0.8.4") verified against the manifest.
pub(crate) fn binary_version() -> Result<&'static str> {
    Ok(captured()?.version.as_str())
}

fn command_policy(method: &str) -> (String, String) {
    // Exact method bytes keep dotted/hyphenated CLI names distinct. This is a
    // policy identifier, not an inferred CLI type or a hardcoded method table.
    let key = format!("c{:x}", Sha256::digest(method.as_bytes()));
    (
        format!("cap.software.threetched.call.{key}@v1"),
        format!("mut.software.threetched.call.{key}@v1"),
    )
}

fn schema_from_capture(captured: &Captured) -> Result<PluginSchema> {
    let root = serde_json::to_value(schemars::schema_for!(ThreetchedState))?;
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        PLUGIN_NAME, VERSION, "Commands discovered from the pinned threetched binary", &root,
    );
    schema.category = "software".into();
    schema.display_name = Some("threetched".into());
    schema.tags = vec!["threetched".into(), "binary".into(), "immutable".into()];
    schema.immutable_paths = root["properties"].as_object().context("missing threetched descriptor fields")?
        .keys().map(|name| format!("/{name}")).collect();
    // Publish closed metadata fields; opaque discovery evidence is sealed in example.
    schema.public_state.paths = ["binary", "manifest", "config_dir", "binary_sha256", "manifest_sha256"]
        .map(|name| format!("/{name}")).into();
    let state = simd_json::serde::to_owned_value(&captured.state)?;
    super::schemars_adapter::apply_state_defaults(&mut schema, &state);
    schema.example = Some(state);
    for method in captured.surface.commands() {
        let input = captured.surface.input_schema(method)?;
        let output = captured.surface.output_schema(method)?;
        for contract in [&input, &output] {
            op_blob::descriptor::validate_json_schema_field_aliases(contract)
                .map_err(anyhow::Error::msg)
                .with_context(|| format!("threetched method {method} has ambiguous transport fields"))?;
        }
        let (capability, subid) = command_policy(method);
        schema.capabilities.insert(capability.clone(), CapabilityDecl {
            id: capability.clone(),
            description: format!("Execute threetched CLI command {method} in the sealed runtime context."),
        });
        schema.methods.insert(method.to_owned(), MethodDecl {
            name: method.to_owned(),
            args: simd_json::serde::to_owned_value(input)?,
            returns: Some(simd_json::serde::to_owned_value(output)?),
            side_effect: SideEffect::Mutation,
            idempotent: false,
            required_capability: Some(capability),
            subid,
        });
    }
    ensure!(!schema.methods.is_empty(), "threetched binary supplied no callable commands");
    Ok(schema)
}

pub fn threetched_schema() -> PluginSchema {
    if !is_schema_capture() {
        return sealed_schema(PLUGIN_NAME).expect("threetched runtime requires its sealed schema");
    }
    schema_from_capture(captured().expect("threetched discovery must succeed before sealing"))
        .expect("threetched discovered contract must be representable")
}

pub fn state_value() -> Result<OwnedValue> {
    if !is_schema_capture() {
        return sealed_state(PLUGIN_NAME);
    }
    Ok(simd_json::serde::to_owned_value(&captured()?.state)?)
}

#[derive(Default)]
pub struct ThreetchedPlugin;

#[async_trait]
impl StatePlugin for ThreetchedPlugin {
    fn name(&self) -> &str { PLUGIN_NAME }
    fn version(&self) -> &str { VERSION }
    fn schema(&self) -> Option<PluginSchema> { Some(threetched_schema()) }
    async fn calculate_diff(&self, current: &OwnedValue, desired: &OwnedValue) -> Result<StateDiff> {
        ensure!(current == desired && *desired == state_value()?, "threetched discovery descriptor is immutable");
        Ok(StateDiff {
            plugin: PLUGIN_NAME.into(), actions: vec![],
            metadata: DiffMetadata { timestamp: chrono::Utc::now().timestamp(), current_hash: String::new(), desired_hash: String::new() },
        })
    }
    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        ensure!(diff.plugin == PLUGIN_NAME && diff.actions.is_empty(), "threetched discovery descriptor is immutable");
        Ok(ApplyResult { success: true, changes_applied: vec![], errors: vec![], checkpoint: None })
    }
    async fn verify_state(&self, desired: &OwnedValue) -> Result<bool> { Ok(*desired == state_value()?) }
    async fn create_checkpoint(&self) -> Result<Checkpoint> { bail!("threetched discovery descriptor has no checkpoints") }
    async fn rollback(&self, _: &Checkpoint) -> Result<()> { bail!("threetched discovery descriptor has no rollback") }
    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities { supports_rollback: false, supports_checkpoints: false, supports_verification: true, atomic_operations: false }
    }
}

struct CancelOnDrop(Arc<AtomicBool>);
impl Drop for CancelOnDrop {
    fn drop(&mut self) { self.0.store(true, Ordering::Release); }
}

/// Preserve the sealed service context. The CLI's own config selector remains
/// discoverable, but it cannot redirect an admitted operation to another root.
fn validate_config_selector(value: &Value, config_dir: &Path, spellings: &[&str]) -> Result<()> {
    let expected = path_text(config_dir)?;
    let one = serde_json::json!([expected]);
    let mut selected = false;
    for spelling in spellings {
        if let Some(selector) = value.get(*spelling) {
            ensure!(!selected, "threetched config selector was supplied through multiple aliases");
            ensure!(selector == &one || selector == &serde_json::json!([one.clone()]), "threetched config selector must select the sealed runtime context");
            selected = true;
        }
    }
    Ok(())
}

fn validate_noninteractive_command(
    method: &str,
    value: &Value,
    surface: &ThreetchedSurface,
) -> Result<()> {
    // Called only after canonical admission, queued-call rechecks and sealed
    // argument validation. These closed refusals cannot contain caller data.
    if method == "skills.edit" {
        return Err(UnsupportedBeforeEffect::new(
            "threetched_skills_edit_unsupported",
            "skills.edit is unavailable in the noninteractive executor; native content editing is not captured",
        ).into());
    }
    if method == "skills.add" {
        let editor_requested = surface.option_spellings(method, "--edit")?
            .iter().any(|spelling| value.get(*spelling).and_then(Value::as_bool) == Some(true));
        if editor_requested {
            return Err(UnsupportedBeforeEffect::new(
                "threetched_skills_add_editor_unsupported",
                "skills.add with an editor is unavailable in the noninteractive executor; omit --edit",
            ).into());
        }
    }
    Ok(())
}

fn prepare_command(method: &str, value: &Value, source: &ThreetchedState) -> Result<Command> {
    let binary = super::chat_router_paths::binary()?;
    let manifest = super::chat_router_paths::manifest()?;
    let config_dir = super::chat_router_paths::config_dir()?;
    ensure!(binary == Path::new(&source.binary) && manifest == Path::new(&source.manifest)
        && config_dir == Path::new(&source.config_dir), "threetched runtime paths changed since seal");
    ensure!(sha256_file(&manifest)? == source.manifest_sha256,
        "threetched manifest changed since seal");
    let snapshot: SurfaceSnapshot = serde_json::from_value(source.surface.clone())?;
    let surface = ThreetchedSurface::from_snapshot(&binary, &snapshot)?;
    ensure!(surface.binary_sha256() == source.binary_sha256, "threetched sealed source digests disagree");
    let descriptor: Value = serde_json::from_reader(File::open(&manifest)?)?;
    manifest_version(&descriptor, surface.binary_sha256())?;
    let config_spellings = surface.option_spellings(method, "--config-dir")?;
    validate_config_selector(value, &config_dir, &config_spellings)?;
    let argv = surface.arguments(method, value).context("invalid threetched CLI arguments")?;
    // No interactive terminal/content-input contract exists. Refuse before
    // constructing or spawning a command; never translate runner failures.
    validate_noninteractive_command(method, value, &surface)?;
    // Match the existing tched-router service owner. This backend is a shared
    // service selected by exact capabilities, never a caller-supplied identity
    // or a guessed mapping from SID1 to an operating-system account.
    let mut command = if nix::unistd::geteuid().is_root() {
        let mut command = Command::new("/usr/bin/chpst");
        command.args(["-u", "jeremy:jeremy"]).arg(surface.binary_path());
        command
    } else {
        let owner = nix::unistd::User::from_name("jeremy")?
            .context("threetched service owner is absent")?;
        ensure!(nix::unistd::geteuid() == owner.uid && nix::unistd::getegid() == owner.gid,
            "threetched dispatch must run as its configured service owner");
        Command::new(surface.binary_path())
    };
    command.args(argv)
        .env_clear()
        .env("PATH", "/usr/local/bin:/usr/bin:/bin")
        .env("HOME", config_dir.join("home"))
        .env("USER", "jeremy")
        .env("THREETCHED_CONFIG_DIR", config_dir)
        .env("LANGUAGE", "en")
        .env("LC_ALL", "C")
        .env("LANG", "C")
        .env("NO_COLOR", "1");
    Ok(command)
}

/// Called only after canonical method admission and its final queued-call
/// recheck. The bounded runner kills/reaps the whole child group on timeout,
/// cancellation or output exhaustion; it does not retry an uncertain result.
pub async fn dispatch(
    method: &str,
    value: &Value,
    source: &ThreetchedState,
    operation: Arc<tokio::sync::MutexGuard<'static, ()>>,
) -> Result<Value> {
    let method = method.to_owned();
    let value = value.clone();
    let source = source.clone();
    let cancelled = Arc::new(AtomicBool::new(false));
    let _cancel_on_drop = CancelOnDrop(cancelled.clone());
    tokio::task::spawn_blocking(move || -> Result<Value> {
        // A cancelled RPC must not release service serialization before the
        // worker has killed and reaped its child group.
        let _operation = operation;
        let mut command = prepare_command(&method, &value, &source)?;
        let output = tched_fs::fuse_process::run_command(&mut command, &cancelled)?;
        ensure!(output.exit == 0, "threetched command exited with {}; inspect the identity-bound method receipt before retrying", output.exit);
        Ok(serde_json::to_value(&output)?)
    }).await.context("threetched execution worker failed")?
}

inventory::submit! {
    crate::default_registry::PluginReg::new(PLUGIN_NAME, |_ctx| Arc::new(ThreetchedPlugin))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn discovered_cli_flags_survive_sealing_and_descriptor_transport_with_admission_policy() {
        use std::os::unix::fs::PermissionsExt;
        use prost::Message;
        use prost_reflect::{DescriptorPool, DynamicMessage};

        let directory = tempfile::tempdir().unwrap();
        let binary = directory.path().join("threetched-fixture");
        // Only advertised introspection paths succeed; this fixture cannot
        // execute a feature operation while generating or transporting input.
        std::fs::write(&binary, r#"#!/bin/sh
case "$*" in
  '--version') printf 'threetched 0.0.1\n' ;;
  'config schema') printf '{"type":"object","properties":{}}\n' ;;
  '--help')
    printf 'Usage: threetched <COMMAND>\n\nCommands:\n  config  Configuration\n  widgets  Widget operations\n  skills  Skill operations\n' ;;
  'config --help')
    printf 'Usage: threetched config <COMMAND>\n\nCommands:\n  schema  Export schema\n' ;;
  'config schema --help') printf 'Usage: threetched config schema\n' ;;
  'widgets --help')
    printf 'Usage: threetched widgets <COMMAND>\n\nCommands:\n  publish  Publish a widget\n' ;;
  'widgets publish --help')
    cat <<'HELP'
Usage: threetched widgets publish [OPTIONS] <NAME>

Arguments:
  <NAME>  Widget name

Options:
  -f, --format <FORMAT>  Output format
          [possible values: json, text]
  -n, --count <COUNT>  Literal CLI value
  -v, --verbose  Verbose output
  -c, --config-dir <CONFIG_DIR>  Runtime configuration
HELP
    ;;
  'skills --help')
    printf 'Usage: threetched skills <COMMAND>\n\nCommands:\n  edit  Edit a skill\n  add  Add a skill\n' ;;
  'skills edit --help')
    printf 'Usage: threetched skills edit <NAME>\n\nArguments:\n  <NAME>  Skill name\n' ;;
  'skills add --help')
    printf 'Usage: threetched skills add [OPTIONS] <NAME>\n\nArguments:\n  <NAME>  Skill name\n\nOptions:\n  -e, --edit  Open editor\n' ;;
  *) exit 91 ;;
esac
"#).unwrap();
        std::fs::set_permissions(&binary, std::fs::Permissions::from_mode(0o755)).unwrap();
        let surface = ThreetchedSurface::capture_with_config(&binary, directory.path()).unwrap();
        let captured = Captured {
            state: ThreetchedState {
                binary: super::super::chat_router_paths::DEFAULT_BINARY.into(),
                manifest: super::super::chat_router_paths::DEFAULT_MANIFEST.into(),
                config_dir: super::super::chat_router_paths::DEFAULT_CONFIG_DIR.into(),
                binary_sha256: surface.binary_sha256().into(),
                manifest_sha256: "a".repeat(64),
                surface: serde_json::to_value(surface.snapshot()).unwrap(),
            },
            surface,
            version: "0.0.1".into(),
        };
        let schema = schema_from_capture(&captured).unwrap();
        let method_name = "widgets.publish";
        let source_input = captured.surface.input_schema(method_name).unwrap();
        let source_output = captured.surface.output_schema(method_name).unwrap();
        let blob = op_blob::blobify_plugin_schema(PLUGIN_NAME, schema);
        let bytes = blob.seal();
        assert!(bytes.len() < 1024 * 1024);
        let pinned = op_blob::BlobRef::from_manifest_pinned(&bytes, &blob.manifest.schema_hash).unwrap();
        let sealed = pinned.state_store_schema().unwrap();
        let declaration = &sealed.methods[method_name];
        assert_eq!(serde_json::to_value(&declaration.args).unwrap(), source_input);
        assert_eq!(serde_json::to_value(declaration.returns.as_ref().unwrap()).unwrap(), source_output);
        assert_eq!(declaration.side_effect, SideEffect::Mutation);
        assert!(!declaration.idempotent);
        let (capability, subid) = command_policy(method_name);
        assert_eq!(declaration.required_capability.as_deref(), Some(capability.as_str()));
        assert_eq!(declaration.subid, subid);
        assert!(sealed.capabilities.contains_key(&capability));
        assert!(sealed.validate_capability_closure().missing.is_empty());
        assert!(sealed.capability_grants.is_empty());

        let manifest = pinned.manifest().unwrap();
        let method_manifest = manifest.methods.iter().find(|method| method.schema_name == method_name).unwrap();
        let pool = DescriptorPool::decode(pinned.descriptor_set()).unwrap();
        let input = pool.get_message_by_name(&method_manifest.input_message).unwrap();
        for spelling in ["--format", "-f", "--count", "-n", "--verbose", "-v", "--config-dir", "-c"] {
            let field = input.get_field_by_name(&op_blob::descriptor::proto_field_name(spelling)).unwrap();
            assert_eq!(field.json_name(), spelling);
        }
        let validator = jsonschema::validator_for(&source_input).unwrap();
        for (spelling, value) in [
            ("--format", serde_json::json!(["json"])),
            ("-f", serde_json::json!(["text"])),
            ("--count", serde_json::json!(["007"])),
            ("-n", serde_json::json!(["007"])),
            ("--verbose", serde_json::json!(true)),
            ("-v", serde_json::json!(true)),
        ] {
            let arguments = serde_json::json!({(spelling):value,"arguments":["sample"]});
            assert!(validator.is_valid(&arguments));
            let message = DynamicMessage::deserialize(input.clone(), &arguments).unwrap();
            let encoded = message.encode_to_vec();
            let decoded = DynamicMessage::decode(input.clone(), encoded.as_slice()).unwrap();
            let transported = serde_json::to_value(decoded).unwrap();
            assert_eq!(transported, arguments);
            assert!(validator.is_valid(&transported));
            let mut expected = vec!["widgets".to_owned(), "publish".to_owned(), spelling.to_owned()];
            if let Some(tokens) = value.as_array() {
                expected.extend(tokens.iter().map(|token| token.as_str().unwrap().to_owned()));
            }
            expected.extend(["--".to_owned(), "sample".to_owned()]);
            assert_eq!(captured.surface.arguments(method_name, &transported).unwrap(), expected);
        }
        assert!(!validator.is_valid(&serde_json::json!({"--count":[7],"arguments":["sample"]})));
        assert!(!validator.is_valid(&serde_json::json!({"--unknown":true,"arguments":["sample"]})));
        assert!(!validator.is_valid(&serde_json::json!({"-f":["json"],"--format":["json"],"arguments":["sample"]})));

        // Context restrictions use aliases from the same sealed snapshot.
        let snapshot: SurfaceSnapshot = serde_json::from_value(captured.state.surface.clone()).unwrap();
        let restored = ThreetchedSurface::from_snapshot(&binary, &snapshot).unwrap();
        let spellings = restored.option_spellings(method_name, "--config-dir").unwrap();
        assert_eq!(spellings, ["-c", "--config-dir"]);
        assert!(validate_config_selector(&serde_json::json!({"-c":["/other/identity"]}),
            Path::new(&captured.state.config_dir), &spellings).is_err());

        let private_name = "private-skill-name";
        let edit = validate_noninteractive_command(
            "skills.edit", &serde_json::json!({"arguments":[private_name]}), &restored,
        ).unwrap_err();
        assert_eq!(edit.downcast_ref::<UnsupportedBeforeEffect>().unwrap().code(),
            "threetched_skills_edit_unsupported");
        assert!(!edit.to_string().contains(private_name));
        let edit_spellings = restored.option_spellings("skills.add", "--edit").unwrap();
        assert_eq!(edit_spellings, ["-e", "--edit"]);
        for spelling in edit_spellings {
            let refusal = validate_noninteractive_command(
                "skills.add", &serde_json::json!({(spelling):true,"arguments":[private_name]}), &restored,
            ).unwrap_err();
            assert_eq!(refusal.downcast_ref::<UnsupportedBeforeEffect>().unwrap().code(),
                "threetched_skills_add_editor_unsupported");
            assert!(refusal.to_string().contains("omit --edit"));
            assert!(!refusal.to_string().contains(private_name));
            validate_noninteractive_command(
                "skills.add", &serde_json::json!({(spelling):false,"arguments":[private_name]}), &restored,
            ).unwrap();
        }
        validate_noninteractive_command(
            "skills.add", &serde_json::json!({"arguments":[private_name]}), &restored,
        ).unwrap();
        validate_noninteractive_command("widgets.publish", &serde_json::json!({}), &restored).unwrap();
    }

    #[test]
    fn command_policy_preserves_distinct_method_identity() {
        let (cap, subid) = command_policy("plugins.install");
        assert_ne!(cap, command_policy("plugins-install").0);
        super::super::common::oscal::validate_subid(&subid).unwrap();
        assert!(cap.starts_with("cap.software.threetched.call."));
    }

    #[test]
    fn config_selector_cannot_escape_sealed_context() {
        let root = Path::new("/var/lib/tched-router");
        // Fixture spellings; production obtains this list from captured help.
        let spellings = ["-c", "--config-dir"];
        validate_config_selector(&serde_json::json!({}), root, &spellings).unwrap();
        for spelling in spellings {
            validate_config_selector(&serde_json::json!({(spelling):["/var/lib/tched-router"]}), root, &spellings).unwrap();
            validate_config_selector(&serde_json::json!({(spelling):[["/var/lib/tched-router"]]}), root, &spellings).unwrap();
            assert!(validate_config_selector(&serde_json::json!({(spelling):["/other/identity"]}), root, &spellings).is_err());
            assert!(validate_config_selector(&serde_json::json!({(spelling):[["/var/lib/tched-router"],["/other/identity"]]}), root, &spellings).is_err());
        }
        assert!(validate_config_selector(&serde_json::json!({"-c":["/var/lib/tched-router"], "--config-dir":["/var/lib/tched-router"]}), root, &spellings).is_err());
    }

    #[test]
    fn cancelled_future_signals_the_owned_process_worker() {
        let flag = Arc::new(AtomicBool::new(false));
        { let _guard = CancelOnDrop(flag.clone()); }
        assert!(flag.load(Ordering::Acquire));
    }
}

//! Binary-discovered threetched methods owned by one sealed plugin contract.
//!
//! The binary supplies command words, flags and token schemas. This plugin owns
//! admission policy; help text cannot establish that a command is read-only.
//! opblob is the sole sealer. Filesystem and transport consumers project its
//! sealed declarations and dispatch through the existing MutationEngine gate.

use std::fs::File;
use std::io::Read;
use std::path::Path;
use std::process::Command;
use std::sync::{Arc, OnceLock, atomic::{AtomicBool, Ordering}};

use anyhow::{Context, Result, bail, ensure};
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::method_receipt::UnsupportedBeforeEffect;
use op_state_store::{CapabilityDecl, MethodDecl, PluginSchema, SideEffect};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::{Digest, Sha256};
use simd_json::OwnedValue;
use tched_fs::threetched_surface::{SurfaceSnapshot, ThreetchedSurface};

pub const PLUGIN_NAME: &str = "threetched";
const VERSION: &str = "1.0.0";
const MANIFEST_FORMAT: &str = "opdbus.threetched.v2";

/// Immutable discovery evidence, never a copy of the running configuration.
/// Capture selectors are build/seal inputs; these paths select the installed
/// runtime and stay identical when the candidate is staged into a release.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ThreetchedState {
    pub binary: String,
    pub manifest: String,
    pub config_dir: String,
    pub binary_sha256: String,
    pub manifest_sha256: String,
    pub surface: Value,
}

struct Captured {
    state: ThreetchedState,
    surface: ThreetchedSurface,
    version: String,
}

static CAPTURED: OnceLock<std::result::Result<Captured, String>> = OnceLock::new();

/// Explicit authoring entry point for opblob and generated bridge contracts.
/// Each opblob command is a new process: every seal captures fresh bytes, shared
/// by all consumers in that invocation. Runtime never initializes this cache.
pub fn prepare_schema_capture() -> Result<()> {
    CAPTURED.get_or_init(|| capture().map_err(|error| format!("{error:#}")))
        .as_ref().map(|_| ()).map_err(|error| anyhow::anyhow!("{error}"))
}

pub(crate) fn is_schema_capture() -> bool {
    CAPTURED.get().is_some()
}

fn captured() -> Result<&'static Captured> {
    CAPTURED
        .get().context("threetched capture requires explicit schema preparation; runtime uses sealed blobs")?
        .as_ref()
        .map_err(|error| anyhow::anyhow!("{error}"))
}

pub(crate) fn sealed_schema(plugin_id: &str) -> Result<PluginSchema> {
    let directory = std::env::var_os("OP_BLOB_CATALOG_DIR")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| op_blob::catalog::DEFAULT_SHM_DIR.into());
    op_blob::catalog::read_plugin_state_store_schema(&directory, plugin_id)
        .with_context(|| format!("missing or invalid sealed {plugin_id} schema in {}", directory.display()))
}

pub(crate) fn sealed_state(plugin_id: &str) -> Result<OwnedValue> {
    sealed_schema(plugin_id)?.example
        .with_context(|| format!("sealed {plugin_id} schema has no discovery descriptor"))
}

pub(crate) fn capture_state() -> Result<&'static ThreetchedState> {
    Ok(&captured()?.state)
}

fn path_text(path: &Path) -> Result<String> {
    Ok(path.to_str().context("threetched path is not UTF-8")?.to_owned())
}

fn sha256_file(path: &Path) -> Result<String> {
    let mut file = File::open(path).with_context(|| format!("open {}", path.display()))?;
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024];
    loop {
        let count = file.read(&mut buffer)?;
        if count == 0 {
            break;
        }
        hasher.update(&buffer[..count]);
    }
    Ok(format!("{:x}", hasher.finalize()))
}

fn manifest_version(manifest: &Value, binary_hash: &str) -> Result<String> {
    ensure!(manifest["format"] == MANIFEST_FORMAT, "unsupported threetched manifest format");
    ensure!(manifest.pointer("/source/mode").and_then(Value::as_str) == Some("unmodified-upstream"),
        "threetched manifest is not unmodified upstream");
    ensure!(manifest.get("patches").is_none(), "threetched manifest still carries the retired patch contract");
    ensure!(manifest.pointer("/artifact/name").and_then(Value::as_str) == Some("threetched"), "manifest is not for the threetched executable");
    ensure!(manifest.pointer("/artifact/sha256").and_then(Value::as_str) == Some(binary_hash), "threetched executable differs from its manifest");
    let upstream_binary = manifest.pointer("/artifact/upstream_binary").and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .context("threetched manifest has no upstream binary")?;
    let tag = manifest.pointer("/upstream/tag").and_then(Value::as_str)
        .context("threetched manifest has no upstream version")?;
    let version = tag.strip_prefix('v').filter(|value| !value.is_empty())
        .context("threetched manifest version must start with v")?;
    Ok(format!("{upstream_binary} {version}"))
}

fn capture() -> Result<Captured> {
    let binary = super::chat_router_paths::binary()?;
    let manifest = super::chat_router_paths::manifest()?;
    let config_dir = super::chat_router_paths::config_dir()?;
    let (capture_binary, capture_manifest) = super::chat_router_paths::capture_paths()?;
    let manifest_sha256 = sha256_file(&capture_manifest)?;
    let descriptor: Value = serde_json::from_reader(File::open(&capture_manifest)?)?;
    let binary_sha256 = sha256_file(&capture_binary)?;
    let version = manifest_version(&descriptor, &binary_sha256)?;
    let bare_version = version.rsplit_once(' ').map(|(_, bare)| bare.to_owned())
        .filter(|bare| !bare.is_empty())
        .expect("manifest_version ends with the bare version");
    let surface = ThreetchedSurface::capture_with_config(&capture_binary, &config_dir)?;
    ensure!(surface.binary_sha256() == binary_sha256, "threetched executable changed during capture");
    ensure!(surface.version() == Some(version.as_str()), "threetched version differs from its manifest");
    ensure!(sha256_file(&capture_manifest)? == manifest_sha256, "threetched manifest changed during capture");
    let state = ThreetchedState {
        binary: path_text(&binary)?,
        manifest: path_text(&manifest)?,
        config_dir: path_text(&config_dir)?,
        binary_sha256: surface.binary_sha256().to_owned(),
        manifest_sha256,
        surface: serde_json::to_value(surface.snapshot())?,
    };
    Ok(Captured { state, surface, version: bare_version })
}

/// The pinned binary surface captured once at seal.
pub(crate) fn surface() -> Result<&'static ThreetchedSurface> {
    Ok(&captured()?.surface)
}

/// The threetched `config schema` document from the same pinned capture.
pub(crate) fn config_schema() -> Result<&'static Value> {
    Ok(captured()?.surface.schema_json())
}

/// The bare upstream version (e.g. "0.8.4") verified against the manifest.
pub(crate) fn binary_version() -> Result<&'static str> {
    Ok(captured()?.version.as_str())
}

fn command_policy(method: &str) -> (String, String) {
    // Exact method bytes keep dotted/hyphenated CLI names distinct. This is a
    // policy identifier, not an inferred CLI type or a hardcoded method table.
    let key = format!("c{:x}", Sha256::digest(method.as_bytes()));
    (
        format!("cap.software.threetched.call.{key}@v1"),
        format!("mut.software.threetched.call.{key}@v1"),
    )
}

fn schema_from_capture(captured: &Captured) -> Result<PluginSchema> {
    let root = serde_json::to_value(schemars::schema_for!(ThreetchedState))?;
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        PLUGIN_NAME, VERSION, "Commands discovered from the pinned threetched binary", &root,
    );
    schema.category = "software".into();
    schema.display_name = Some("threetched".into());
    schema.tags = vec!["threetched".into(), "binary".into(), "immutable".into()];
    schema.immutable_paths = root["properties"].as_object().context("missing threetched descriptor fields")?
        .keys().map(|name| format!("/{name}")).collect();
    // Publish closed metadata fields; opaque discovery evidence is sealed in example.
    schema.public_state.paths = ["binary", "manifest", "config_dir", "binary_sha256", "manifest_sha256"]
        .map(|name| format!("/{name}")).into();
    let state = simd_json::serde::to_owned_value(&captured.state)?;
    super::schemars_adapter::apply_state_defaults(&mut schema, &state);
    schema.example = Some(state);
    for method in captured.surface.commands() {
        let input = captured.surface.input_schema(method)?;
        let output = captured.surface.output_schema(method)?;
        for contract in [&input, &output] {
            op_blob::descriptor::validate_json_schema_field_aliases(contract)
                .map_err(anyhow::Error::msg)
                .with_context(|| format!("threetched method {method} has ambiguous transport fields"))?;
        }
        let (capability, subid) = command_policy(method);
        schema.capabilities.insert(capability.clone(), CapabilityDecl {
            id: capability.clone(),
            description: format!("Execute threetched CLI command {method} in the sealed runtime context."),
        });
        schema.methods.insert(method.to_owned(), MethodDecl {
            name: method.to_owned(),
            args: simd_json::serde::to_owned_value(input)?,
            returns: Some(simd_json::serde::to_owned_value(output)?),
            side_effect: SideEffect::Mutation,
            idempotent: false,
            required_capability: Some(capability),
            subid,
        });
    }
    ensure!(!schema.methods.is_empty(), "threetched binary supplied no callable commands");
    Ok(schema)
}

pub fn threetched_schema() -> PluginSchema {
    if !is_schema_capture() {
        return sealed_schema(PLUGIN_NAME).expect("threetched runtime requires its sealed schema");
    }
    schema_from_capture(captured().expect("threetched discovery must succeed before sealing"))
        .expect("threetched discovered contract must be representable")
}

pub fn state_value() -> Result<OwnedValue> {
    if !is_schema_capture() {
        return sealed_state(PLUGIN_NAME);
    }
    Ok(simd_json::serde::to_owned_value(&captured()?.state)?)
}

#[derive(Default)]
pub struct ThreetchedPlugin;

#[async_trait]
impl StatePlugin for ThreetchedPlugin {
    fn name(&self) -> &str { PLUGIN_NAME }
    fn version(&self) -> &str { VERSION }
    fn schema(&self) -> Option<PluginSchema> { Some(threetched_schema()) }
    async fn calculate_diff(&self, current: &OwnedValue, desired: &OwnedValue) -> Result<StateDiff> {
        ensure!(current == desired && *desired == state_value()?, "threetched discovery descriptor is immutable");
        Ok(StateDiff {
            plugin: PLUGIN_NAME.into(), actions: vec![],
            metadata: DiffMetadata { timestamp: chrono::Utc::now().timestamp(), current_hash: String::new(), desired_hash: String::new() },
        })
    }
    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        ensure!(diff.plugin == PLUGIN_NAME && diff.actions.is_empty(), "threetched discovery descriptor is immutable");
        Ok(ApplyResult { success: true, changes_applied: vec![], errors: vec![], checkpoint: None })
    }
    async fn verify_state(&self, desired: &OwnedValue) -> Result<bool> { Ok(*desired == state_value()?) }
    async fn create_checkpoint(&self) -> Result<Checkpoint> { bail!("threetched discovery descriptor has no checkpoints") }
    async fn rollback(&self, _: &Checkpoint) -> Result<()> { bail!("threetched discovery descriptor has no rollback") }
    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities { supports_rollback: false, supports_checkpoints: false, supports_verification: true, atomic_operations: false }
    }
}

struct CancelOnDrop(Arc<AtomicBool>);
impl Drop for CancelOnDrop {
    fn drop(&mut self) { self.0.store(true, Ordering::Release); }
}

/// Preserve the sealed service context. The CLI's own config selector remains
/// discoverable, but it cannot redirect an admitted operation to another root.
fn validate_config_selector(value: &Value, config_dir: &Path, spellings: &[&str]) -> Result<()> {
    let expected = path_text(config_dir)?;
    let one = serde_json::json!([expected]);
    let mut selected = false;
    for spelling in spellings {
        if let Some(selector) = value.get(*spelling) {
            ensure!(!selected, "threetched config selector was supplied through multiple aliases");
            ensure!(selector == &one || selector == &serde_json::json!([one.clone()]), "threetched config selector must select the sealed runtime context");
            selected = true;
        }
    }
    Ok(())
}

fn validate_noninteractive_command(
    method: &str,
    value: &Value,
    surface: &ThreetchedSurface,
) -> Result<()> {
    // Called only after canonical admission, queued-call rechecks and sealed
    // argument validation. These closed refusals cannot contain caller data.
    if method == "skills.edit" {
        return Err(UnsupportedBeforeEffect::new(
            "threetched_skills_edit_unsupported",
            "skills.edit is unavailable in the noninteractive executor; native content editing is not captured",
        ).into());
    }
    if method == "skills.add" {
        let editor_requested = surface.option_spellings(method, "--edit")?
            .iter().any(|spelling| value.get(*spelling).and_then(Value::as_bool) == Some(true));
        if editor_requested {
            return Err(UnsupportedBeforeEffect::new(
                "threetched_skills_add_editor_unsupported",
                "skills.add with an editor is unavailable in the noninteractive executor; omit --edit",
            ).into());
        }
    }
    Ok(())
}

fn prepare_command(method: &str, value: &Value, source: &ThreetchedState) -> Result<Command> {
    let binary = super::chat_router_paths::binary()?;
    let manifest = super::chat_router_paths::manifest()?;
    let config_dir = super::chat_router_paths::config_dir()?;
    ensure!(binary == Path::new(&source.binary) && manifest == Path::new(&source.manifest)
        && config_dir == Path::new(&source.config_dir), "threetched runtime paths changed since seal");
    ensure!(sha256_file(&manifest)? == source.manifest_sha256,
        "threetched manifest changed since seal");
    let snapshot: SurfaceSnapshot = serde_json::from_value(source.surface.clone())?;
    let surface = ThreetchedSurface::from_snapshot(&binary, &snapshot)?;
    ensure!(surface.binary_sha256() == source.binary_sha256, "threetched sealed source digests disagree");
    let descriptor: Value = serde_json::from_reader(File::open(&manifest)?)?;
    manifest_version(&descriptor, surface.binary_sha256())?;
    let config_spellings = surface.option_spellings(method, "--config-dir")?;
    validate_config_selector(value, &config_dir, &config_spellings)?;
    let argv = surface.arguments(method, value).context("invalid threetched CLI arguments")?;
    // No interactive terminal/content-input contract exists. Refuse before
    // constructing or spawning a command; never translate runner failures.
    validate_noninteractive_command(method, value, &surface)?;
    // Match the existing tched-router service owner. This backend is a shared
    // service selected by exact capabilities, never a caller-supplied identity
    // or a guessed mapping from SID1 to an operating-system account.
    let mut command = if nix::unistd::geteuid().is_root() {
        let mut command = Command::new("/usr/bin/chpst");
        command.args(["-u", "jeremy:jeremy"]).arg(surface.binary_path());
        command
    } else {
        let owner = nix::unistd::User::from_name("jeremy")?
            .context("threetched service owner is absent")?;
        ensure!(nix::unistd::geteuid() == owner.uid && nix::unistd::getegid() == owner.gid,
            "threetched dispatch must run as its configured service owner");
        Command::new(surface.binary_path())
    };
    command.args(argv)
        .env_clear()
        .env("PATH", "/usr/local/bin:/usr/bin:/bin")
        .env("HOME", config_dir.join("home"))
        .env("USER", "jeremy")
        .env("THREETCHED_CONFIG_DIR", config_dir)
        .env("LANGUAGE", "en")
        .env("LC_ALL", "C")
        .env("LANG", "C")
        .env("NO_COLOR", "1");
    Ok(command)
}

/// Called only after canonical method admission and its final queued-call
/// recheck. The bounded runner kills/reaps the whole child group on timeout,
/// cancellation or output exhaustion; it does not retry an uncertain result.
pub async fn dispatch(
    method: &str,
    value: &Value,
    source: &ThreetchedState,
    operation: Arc<tokio::sync::MutexGuard<'static, ()>>,
) -> Result<Value> {
    let method = method.to_owned();
    let value = value.clone();
    let source = source.clone();
    let cancelled = Arc::new(AtomicBool::new(false));
    let _cancel_on_drop = CancelOnDrop(cancelled.clone());
    tokio::task::spawn_blocking(move || -> Result<Value> {
        // A cancelled RPC must not release service serialization before the
        // worker has killed and reaped its child group.
        let _operation = operation;
        let mut command = prepare_command(&method, &value, &source)?;
        let output = tched_fs::fuse_process::run_command(&mut command, &cancelled)?;
        ensure!(output.exit == 0, "threetched command exited with {}; inspect the identity-bound method receipt before retrying", output.exit);
        Ok(serde_json::to_value(&output)?)
    }).await.context("threetched execution worker failed")?
}

inventory::submit! {
    crate::default_registry::PluginReg::new(PLUGIN_NAME, |_ctx| Arc::new(ThreetchedPlugin))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn discovered_cli_flags_survive_sealing_and_descriptor_transport_with_admission_policy() {
        use std::os::unix::fs::PermissionsExt;
        use prost::Message;
        use prost_reflect::{DescriptorPool, DynamicMessage};

        let directory = tempfile::tempdir().unwrap();
        let binary = directory.path().join("threetched-fixture");
        // Only advertised introspection paths succeed; this fixture cannot
        // execute a feature operation while generating or transporting input.
        std::fs::write(&binary, r#"#!/bin/sh
case "$*" in
  '--version') printf 'threetched 0.0.1\n' ;;
  'config schema') printf '{"type":"object","properties":{}}\n' ;;
  '--help')
    printf 'Usage: threetched <COMMAND>\n\nCommands:\n  config  Configuration\n  widgets  Widget operations\n  skills  Skill operations\n' ;;
  'config --help')
    printf 'Usage: threetched config <COMMAND>\n\nCommands:\n  schema  Export schema\n' ;;
  'config schema --help') printf 'Usage: threetched config schema\n' ;;
  'widgets --help')
    printf 'Usage: threetched widgets <COMMAND>\n\nCommands:\n  publish  Publish a widget\n' ;;
  'widgets publish --help')
    cat <<'HELP'
Usage: threetched widgets publish [OPTIONS] <NAME>

Arguments:
  <NAME>  Widget name

Options:
  -f, --format <FORMAT>  Output format
          [possible values: json, text]
  -n, --count <COUNT>  Literal CLI value
  -v, --verbose  Verbose output
  -c, --config-dir <CONFIG_DIR>  Runtime configuration
HELP
    ;;
  'skills --help')
    printf 'Usage: threetched skills <COMMAND>\n\nCommands:\n  edit  Edit a skill\n  add  Add a skill\n' ;;
  'skills edit --help')
    printf 'Usage: threetched skills edit <NAME>\n\nArguments:\n  <NAME>  Skill name\n' ;;
  'skills add --help')
    printf 'Usage: threetched skills add [OPTIONS] <NAME>\n\nArguments:\n  <NAME>  Skill name\n\nOptions:\n  -e, --edit  Open editor\n' ;;
  *) exit 91 ;;
esac
"#).unwrap();
        std::fs::set_permissions(&binary, std::fs::Permissions::from_mode(0o755)).unwrap();
        let surface = ThreetchedSurface::capture_with_config(&binary, directory.path()).unwrap();
        let captured = Captured {
            state: ThreetchedState {
                binary: super::super::chat_router_paths::DEFAULT_BINARY.into(),
                manifest: super::super::chat_router_paths::DEFAULT_MANIFEST.into(),
                config_dir: super::super::chat_router_paths::DEFAULT_CONFIG_DIR.into(),
                binary_sha256: surface.binary_sha256().into(),
                manifest_sha256: "a".repeat(64),
                surface: serde_json::to_value(surface.snapshot()).unwrap(),
            },
            surface,
            version: "0.0.1".into(),
        };
        let schema = schema_from_capture(&captured).unwrap();
        let method_name = "widgets.publish";
        let source_input = captured.surface.input_schema(method_name).unwrap();
        let source_output = captured.surface.output_schema(method_name).unwrap();
        let blob = op_blob::blobify_plugin_schema(PLUGIN_NAME, schema);
        let bytes = blob.seal();
        assert!(bytes.len() < 1024 * 1024);
        let pinned = op_blob::BlobRef::from_manifest_pinned(&bytes, &blob.manifest.schema_hash).unwrap();
        let sealed = pinned.state_store_schema().unwrap();
        let declaration = &sealed.methods[method_name];
        assert_eq!(serde_json::to_value(&declaration.args).unwrap(), source_input);
        assert_eq!(serde_json::to_value(declaration.returns.as_ref().unwrap()).unwrap(), source_output);
        assert_eq!(declaration.side_effect, SideEffect::Mutation);
        assert!(!declaration.idempotent);
        let (capability, subid) = command_policy(method_name);
        assert_eq!(declaration.required_capability.as_deref(), Some(capability.as_str()));
        assert_eq!(declaration.subid, subid);
        assert!(sealed.capabilities.contains_key(&capability));
        assert!(sealed.validate_capability_closure().missing.is_empty());
        assert!(sealed.capability_grants.is_empty());

        let manifest = pinned.manifest().unwrap();
        let method_manifest = manifest.methods.iter().find(|method| method.schema_name == method_name).unwrap();
        let pool = DescriptorPool::decode(pinned.descriptor_set()).unwrap();
        let input = pool.get_message_by_name(&method_manifest.input_message).unwrap();
        for spelling in ["--format", "-f", "--count", "-n", "--verbose", "-v", "--config-dir", "-c"] {
            let field = input.get_field_by_name(&op_blob::descriptor::proto_field_name(spelling)).unwrap();
            assert_eq!(field.json_name(), spelling);
        }
        let validator = jsonschema::validator_for(&source_input).unwrap();
        for (spelling, value) in [
            ("--format", serde_json::json!(["json"])),
            ("-f", serde_json::json!(["text"])),
            ("--count", serde_json::json!(["007"])),
            ("-n", serde_json::json!(["007"])),
            ("--verbose", serde_json::json!(true)),
            ("-v", serde_json::json!(true)),
        ] {
            let arguments = serde_json::json!({(spelling):value,"arguments":["sample"]});
            assert!(validator.is_valid(&arguments));
            let message = DynamicMessage::deserialize(input.clone(), &arguments).unwrap();
            let encoded = message.encode_to_vec();
            let decoded = DynamicMessage::decode(input.clone(), encoded.as_slice()).unwrap();
            let transported = serde_json::to_value(decoded).unwrap();
            assert_eq!(transported, arguments);
            assert!(validator.is_valid(&transported));
            let mut expected = vec!["widgets".to_owned(), "publish".to_owned(), spelling.to_owned()];
            if let Some(tokens) = value.as_array() {
                expected.extend(tokens.iter().map(|token| token.as_str().unwrap().to_owned()));
            }
            expected.extend(["--".to_owned(), "sample".to_owned()]);
            assert_eq!(captured.surface.arguments(method_name, &transported).unwrap(), expected);
        }
        assert!(!validator.is_valid(&serde_json::json!({"--count":[7],"arguments":["sample"]})));
        assert!(!validator.is_valid(&serde_json::json!({"--unknown":true,"arguments":["sample"]})));
        assert!(!validator.is_valid(&serde_json::json!({"-f":["json"],"--format":["json"],"arguments":["sample"]})));

        // Context restrictions use aliases from the same sealed snapshot.
        let snapshot: SurfaceSnapshot = serde_json::from_value(captured.state.surface.clone()).unwrap();
        let restored = ThreetchedSurface::from_snapshot(&binary, &snapshot).unwrap();
        let spellings = restored.option_spellings(method_name, "--config-dir").unwrap();
        assert_eq!(spellings, ["-c", "--config-dir"]);
        assert!(validate_config_selector(&serde_json::json!({"-c":["/other/identity"]}),
            Path::new(&captured.state.config_dir), &spellings).is_err());

        let private_name = "private-skill-name";
        let edit = validate_noninteractive_command(
            "skills.edit", &serde_json::json!({"arguments":[private_name]}), &restored,
        ).unwrap_err();
        assert_eq!(edit.downcast_ref::<UnsupportedBeforeEffect>().unwrap().code(),
            "threetched_skills_edit_unsupported");
        assert!(!edit.to_string().contains(private_name));
        let edit_spellings = restored.option_spellings("skills.add", "--edit").unwrap();
        assert_eq!(edit_spellings, ["-e", "--edit"]);
        for spelling in edit_spellings {
            let refusal = validate_noninteractive_command(
                "skills.add", &serde_json::json!({(spelling):true,"arguments":[private_name]}), &restored,
            ).unwrap_err();
            assert_eq!(refusal.downcast_ref::<UnsupportedBeforeEffect>().unwrap().code(),
                "threetched_skills_add_editor_unsupported");
            assert!(refusal.to_string().contains("omit --edit"));
            assert!(!refusal.to_string().contains(private_name));
            validate_noninteractive_command(
                "skills.add", &serde_json::json!({(spelling):false,"arguments":[private_name]}), &restored,
            ).unwrap();
        }
        validate_noninteractive_command(
            "skills.add", &serde_json::json!({"arguments":[private_name]}), &restored,
        ).unwrap();
        validate_noninteractive_command("widgets.publish", &serde_json::json!({}), &restored).unwrap();
    }

    #[test]
    fn command_policy_preserves_distinct_method_identity() {
        let (cap, subid) = command_policy("plugins.install");
        assert_ne!(cap, command_policy("plugins-install").0);
        super::super::common::oscal::validate_subid(&subid).unwrap();
        assert!(cap.starts_with("cap.software.threetched.call."));
    }

    #[test]
    fn config_selector_cannot_escape_sealed_context() {
        let root = Path::new("/var/lib/tched-router");
        // Fixture spellings; production obtains this list from captured help.
        let spellings = ["-c", "--config-dir"];
        validate_config_selector(&serde_json::json!({}), root, &spellings).unwrap();
        for spelling in spellings {
            validate_config_selector(&serde_json::json!({(spelling):["/var/lib/tched-router"]}), root, &spellings).unwrap();
            validate_config_selector(&serde_json::json!({(spelling):[["/var/lib/tched-router"]]}), root, &spellings).unwrap();
            assert!(validate_config_selector(&serde_json::json!({(spelling):["/other/identity"]}), root, &spellings).is_err());
            assert!(validate_config_selector(&serde_json::json!({(spelling):[["/var/lib/tched-router"],["/other/identity"]]}), root, &spellings).is_err());
        }
        assert!(validate_config_selector(&serde_json::json!({"-c":["/var/lib/tched-router"], "--config-dir":["/var/lib/tched-router"]}), root, &spellings).is_err());
    }

    #[test]
    fn cancelled_future_signals_the_owned_process_worker() {
        let flag = Arc::new(AtomicBool::new(false));
        { let _guard = CancelOnDrop(flag.clone()); }
        assert!(flag.load(Ordering::Acquire));
    }
